head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
scwin.gAcptNo;
scwin.gIsurCd;
scwin.gPageSize = 10; //페이지 size
scwin.gTotalCnt = 0; //전체 row
scwin.gPageNoCnt = 10; //page 번호 개수
scwin.vCurrPageNo = 0; //현재 선택된 페이지번호
scwin.gISUR_CD;
scwin.gCOM_NM;
scwin.vScrenID = 'ULDSTF35820.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //  기간 from~ to  셋팅	
    vCurDate = $c.ut.cGetToday("yyyymmdd");
    edt_FromDate.setValue($c.ut.cGetMinusYear(vCurDate, 1)); //  1년전  날짜
    edt_ToDate.setValue($c.ut.cGetToday("yyyymmdd")); // 현재날짜
    edt_baseDate.setValue(vCurDate);
    dts_design_releas_rsn.DataID = "/CodeAction.do?method=listCodeValueName" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=AA";
    dts_design_releas_rsn.Reset();

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

};X < !불성실지정예고--;
클릭-- > function() {
    // 일자 체크
    if ($c.stf.getObjectValue(edt_FromDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_FromDate.focus();
        return;
    }

    // 일자 체크
    if ($c.stf.getObjectValue(edt_ToDate).length < 8) {
        $c.win.alert("일자 올바르게 입력하십시오.");
        edt_ToDate.focus();
        return;
    }
    if ($c.stf.compareFromToDate2(edt_FromDate, edt_ToDate) == false) {
        return;
    }
    scwin.fn_Search();
};
scwin.getChkValue = function(obj) {
    //return (obj.checked) ? "Y" : "N";
    if (obj.checked == true) {
        return obj.getValue();
    } else {
        return "0";
    }
};
scwin.fn_Search = function() {
    scwin.vCurrPageNo = 0;
    txb_TotalCnt.setValue("총건수 : ");
    var bndListStat = scwin.getChkValue(chb_ListStatCd);
    if (bndListStat == "0") {
        bndListStat = "2"; //채권공시 해제법인

    }
    if (MaxTab_01.getSelectedTabIndex() == 1) {
        //채권매매거래정지
        var url_list = "/UnfaithfulDesign.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=srchInvstWarnBndLst&inputMessageId=INVSTWARN_BOND_INOUT" + "&outputMessageId=INVSTWARN_BOND_INOUT";
        var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd_1) + "&BASE_DD=" + $c.stf.getObjectValue(edt_baseDate) + "&LST_CD=" + $c.stf.getObjectValue(chb_ListStatCd);

        // 그리드의 데이타 조회
        dts_invstwarn_list.DataID = encodeURI(url_list + url_cond);
        dts_invstwarn_list.reset();
        $c.cm.ShowWin(grd_invstwarn_list);
    } else if (MaxTab_01.getSelectedTabIndex() == 2) {
        //채권매매거래정지해제
        var url_list = "/UnfaithfulDesign.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=srchInvstWarnBndHistLst&inputMessageId=INVSTWARN_BOND_INOUT" + "&outputMessageId=TRHALTBOND_OUT";
        var url_cond = "&ISUR_CD=" + $c.stf.getObjectValue(txb_isur_cd) + "&FROM_DATE=" + $c.stf.getObjectValue(edt_FromDate) + "&TO_DATE=" + $c.stf.getObjectValue(edt_ToDate) + "&LST_CD=" + $c.stf.getObjectValue(rdo_MKT_ID) + "&DESIGN_TP_CD=" + $c.stf.getObjectValue(rdo_desnrels) + "&DESNRELS_RSN=" + $c.stf.getObjectValue(cmb_rsn);

        // 그리드의 데이타 조회
        dts_invstwarn_hist_list.DataID = encodeURI(url_list + url_cond);
        dts_invstwarn_hist_list.reset();
        $c.cm.ShowWin(grd_trdhistbond_list_2);
    }
};




// 그리드에서 클릭 row의 변수셋팅
//매매거래정지
scwin.fn_setContnId_list = function(obj) {
    scwin.gAcptNo = dts_invstwarn_list.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_invstwarn_list.getCellData(eval(obj), "ISUR_CD");
};


//매매거래정지해제
scwin.fn_setContnId_list_2 = function(obj) {
    scwin.gAcptNo = dts_invstwarn_hist_list.getCellData(eval(obj), "ACPT_NO");
    scwin.gIsurCd = dts_invstwarn_hist_list.getCellData(eval(obj), "ISUR_CD");
};
scwin.grd_invstwarn_list_OnDblClick = function(row, colid) {
    scwin.fn_setContnId_list(row);
    if (colid == "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "ISU_NM") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    }
};
scwin.grd_trdhistbond_list_2_OnDblClick = function(row, colid) {
    scwin.fn_setContnId_list_2(row);
    if (colid == "COM_NM") {
        $c.stf.fn_PopupCorpInfo();
    } else if (colid == "DESNRELS_DD") {
        //2017-11-29 KBoY 비공개 첨부서류 볼 수 없음.
        $c.stf.fn_OpenDisclViewer(scwin.gAcptNo, "R", scwin.vScrenID);
    }
};
scwin.dts_invstwarn_list_OnLoadError = function() {
    $c.stf.alert_error(dts_invstwarn_list);
    $c.cm.CloseWin('', grd_invstwarn_list);
};
scwin.dts_invstwarn_list_OnLoadCompleted = function(rowcount) {
    if (dts_invstwarn_list.errorMsg) {
        $c.win.alert(dts_invstwarn_list.errorMsg);
    } else {
        txb_TotalCnt.setValue("총건수 : " + rowcount);
        //alert(txb_TotalCnt.value );

    }
    $c.cm.CloseWin(rowcount, grd_invstwarn_list);
};
scwin.dts_invstwarn_hist_list_OnLoadError = function() {
    $c.stf.alert_error(dts_invstwarn_hist_list);
    $c.cm.CloseWin('', grd_trdhistbond_list_2);
};
scwin.dts_invstwarn_hist_list_OnLoadCompleted = function(rowcount) {
    if (dts_invstwarn_hist_list.errorMsg) {
        $c.win.alert(dts_invstwarn_hist_list.errorMsg);
    } else {
        txb_TotalCnt_2.setValue("총건수 : " + rowcount);
        //alert(txb_TotalCnt.value );

    }
    $c.cm.CloseWin(rowcount, grd_trdhistbond_list_2);
};
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    if (skw != "" && foColum == "1") {
        f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
        f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
        if (f1.indexOf(skw) != -1 || f2.indexOf(skw) != -1) return true;

        else return false;
    } else return true;
};
scwin.btn_Search_onclick = function() {
    fn_CheckCond();
};
scwin.txb_isur_cd_1_onfocus = function() {
    $c.cm.fn_com_isur(txb_isur_cd_1, txb_com_abbrv_1);
    scwin.gISUR_CD = txb_isur_cd_1;
    scwin.gCOM_NM = txb_com_abbrv_1;
    Grd_com_isur.style.top = "80px";
    Grd_com_isur.style.left = "105px";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onfocus = function() {
    $c.cm.fn_com_isur(txb_isur_cd, txb_com_abbrv);
    scwin.gISUR_CD = txb_isur_cd;
    scwin.gCOM_NM = txb_com_abbrv;
    Grd_com_isur.style.top = "130px";
    Grd_com_isur.style.left = "105px";
    Grd_com_isur.style.display = "none";
};
scwin.txb_isur_cd_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd.getValue() == "") {
        txb_com_abbrv.setValue("");
    }
};
scwin.txb_isur_cd_1_onblur = function() {
    if (stFocusGrid == false) {
        Grd_com_isur.style.display = "none";
    }
    if (txb_isur_cd_1.getValue() == "") {
        txb_com_abbrv_1.setValue("");
    }
};
scwin.txb_isur_cd_onkeyup = function() {
    if (txb_isur_cd.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.txb_isur_cd_1_onkeyup = function() {
    if (txb_isur_cd_1.getValue() == "") {
        Grd_com_isur.style.display = "none";
    } else {
        if (window.event.keyCode == 40) {
            //아래화살표눌렀을때 그리드로 포커스
            Grd_com_isur.focus();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
scwin.img_com_srch_onclick = function() {
    $c.cm.IsurcdSearchBond(txb_isur_cd, txb_com_abbrv);
};
scwin.img_com_srch_1_onclick = function() {
    $c.cm.IsurcdSearchBond(txb_isur_cd_1, txb_com_abbrv_1);
};
scwin.img_FromCal_onclick = function() {
    popUpCalendar2(edt_FromDate);
};
scwin.img_ToCal_onclick = function() {
    popUpCalendar2(edt_ToDate);
};
scwin.cmb_PeriodTp_OnSelChange = function() {
    var vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
    $c.stf.fn_setFromToDate(vTp, edt_FromDate, edt_ToDate);
};
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode == '13') {
        $c.cm.fn_com_Confirm_set2(scwin.gISUR_CD, scwin.gCOM_NM);
    }
};
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set2(scwin.gISUR_CD, scwin.gCOM_NM);
};
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};
scwin.Grd_com_isur_OnSetFocus = function() {
    stFocusGrid = true;
};
scwin.Grd_com_isur_OnKillFocus = function() {
    stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
scwin.img_toExcel_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_invstwarn_list, "상장채권매매거래정지", "", "8");
};
scwin.img_toExcel_2_onclick = function() {
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
    $c.data.downloadGridViewExcel(grd_trdhistbond_list_2, "상장채권매매거래정지해제", "", "8");
};
scwin.gform_onload = function() {
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    scwin.fn_SetCode();
    Grd_com_isur.style.display = "none";
    //	fn_com_isur(txb_isur_cd_1, txb_com_abbrv_1);
    fn_CheckCond();
};
scwin.rdo_MKT_ID_OnSelChange = function() {
    //fn_SetCtrlByMktId();

};
scwin.img_4_onclick = function() {
    popUpCalendar2(edt_baseDate);
};
scwin.img_3_onclick = function() {
    scwin.fn_Search();
};
scwin.rdo_desnrels_OnSelChange = function() {
    var rsnVal = $c.stf.getObjectValue(rdo_desnrels);
    if (rsnVal == '0' || rsnVal == '1') {
        dts_design_releas_rsn.DataID = "/CodeAction.do?method=listCodeValueName" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=INVSTWARN_BND_DESIGN_RSN_CD";
    } else if (rsnVal == '2') {
        dts_design_releas_rsn.DataID = "/CodeAction.do?method=listCodeValueName" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=INVSTWARN_BND_RELEAS_RSN_CD";
    } else {
        dts_design_releas_rsn.DataID = "/CodeAction.do?method=listCodeValueName" + "&inputMessageId=CODEVALUE_INOUT&outputMessageId=CODE_OUT" + "&FOR=R&CD_ENG_NM=AA";
    }
    dts_design_releas_rsn.Reset();
};
